    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==0:
                nb=[g[r+a][c+b] for a in(-1,0,1) for b in(-1,0,1) if (a,b)!=(0,0)]
                if 3 in nb: seed=(r,c)
    out=[row[:] for row in g]
    for r in range(len(g)):
        for c in range(len(g[0])):
